#!/usr/bin/env node
/**
 * Behavior Guard — Report Renderer
 *
 * Combines .github/.pipeline-context/verify/<id>.behavior.facts.json (script) with
 * .github/.pipeline-context/verify/<id>.behavior.verdict.json (agent) into
 * docs/agent_output/04-verify/behavior_<id>.md.
 *
 * Usage:
 *   node scripts/render-behavior.js --all
 *   node scripts/render-behavior.js --story JIRA-001
 */
const fs = require('fs');
const path = require('path');
const {
  rel, listStep1Changes, factsPathFor, verdictPathFor, reportPathFor, rewriteVerifyIndex,
} = require('./lib/verify');

const VERDICTS = ['BEHAVIOR_PRESERVED', 'BEHAVIOR_CHANGED', 'INCONCLUSIVE'];
const REQUIRED = [
  ['verdict', (v) => VERDICTS.includes(v.verdict)],
  ['plain_summary', (v) => typeof v.plain_summary === 'string' && v.plain_summary.trim()],
  ['in_scope_changes', (v) => Array.isArray(v.in_scope_changes)],
  ['out_of_scope_changes', (v) => Array.isArray(v.out_of_scope_changes)],
  ['reasoning', (v) => typeof v.reasoning === 'string' && v.reasoning.trim()],
];

function validate(v) {
  const missing = REQUIRED.filter(([, check]) => !check(v)).map(([k]) => k);
  if (missing.length) throw new Error(`behavior verdict is missing required field(s): ${missing.join(', ')}. See templates/behavior.schema.json.`);
  if (v.verdict === 'BEHAVIOR_CHANGED' && !v.out_of_scope_changes.length) {
    throw new Error('verdict is BEHAVIOR_CHANGED but out_of_scope_changes is empty — name at least one change.');
  }
}

function bullets(items, empty = '_none_') {
  if (!items || !items.length) return [empty];
  return items.map((i) => `- ${i}`);
}

function render(facts, verdict) {
  const out = [];
  out.push(`# Behavior guard — ${facts.id}`);
  out.push('');
  out.push(`## ${facts.title}`);
  out.push('');
  out.push(`> ${verdict.plain_summary.trim()}`);
  out.push('');
  out.push(`_Generated by the existing-app test agent on ${new Date().toISOString().slice(0, 10)}. Facts collected ${facts.generatedAt}._`);
  out.push('');

  out.push('## At a glance', '');
  out.push('| | |', '|---|---|');
  out.push(`| **Verdict** | ${verdict.verdict} |`);
  out.push(`| **Confidence** | ${verdict.confidence || 'not stated'} |`);
  out.push(`| **Out-of-scope changes** | ${verdict.out_of_scope_changes.length} |`);
  out.push('');

  out.push('## In-scope changes (explained by the plan)', '');
  bullets(verdict.in_scope_changes).forEach((b) => out.push(b));
  out.push('');

  out.push('## Out-of-scope changes', '');
  bullets(verdict.out_of_scope_changes).forEach((b) => out.push(b));
  out.push('');

  out.push('## Reasoning', '', verdict.reasoning.trim(), '');
  out.push('---', '', `Source development report: \`${facts.sources.devReport}\`.`, '');
  return out.join('\n');
}

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === '--story' || a === '-s') args.story = argv[++i];
    else if (a === '--all' || a === '-a') args.all = true;
  }
  return args;
}

function renderOne(id) {
  const ff = factsPathFor(id, 'behavior');
  if (!fs.existsSync(ff)) throw new Error(`No facts at ${rel(ff)}. Run collect-behavior.js --story ${id} first.`);
  const facts = JSON.parse(fs.readFileSync(ff, 'utf8'));

  const vf = verdictPathFor(id, 'behavior');
  if (!fs.existsSync(vf)) throw new Error(`No verdict at ${rel(vf)}. Read the briefing and write it, per templates/behavior.schema.json.`);
  const verdict = JSON.parse(fs.readFileSync(vf, 'utf8'));
  validate(verdict);

  const target = reportPathFor(id, 'behavior');
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, render(facts, verdict));
  return { id, verdict: verdict.verdict, report: rel(target) };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.all) {
    const targets = listStep1Changes();
    const written = []; const skipped = [];
    for (const t of targets) {
      try { const r = renderOne(t.id); written.push(r); console.log(`${r.id.padEnd(10)} ${r.verdict.padEnd(18)} -> ${r.report}`); } catch (err) { skipped.push(t.id); console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`); }
    }
    rewriteVerifyIndex();
    console.log(`\nWrote ${written.length}/${targets.length} report(s).`);
    if (skipped.length) process.exitCode = 1;
    return;
  }
  if (!args.story) throw new Error('Missing --story or --all.');
  const r = renderOne(args.story);
  rewriteVerifyIndex();
  console.log(`Behavior guard — wrote ${r.report} (${r.verdict})`);
}

try {
  main();
} catch (err) {
  console.error('Rendering failed:', err.message);
  process.exit(1);
}
